draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+120, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2-30, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2+30, H/2+90);
  ctx.stroke();

  // draw thought bubble
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2+80, H/2+60, 40, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2+80, H/2+60, 40, 0, 2*Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1189', W/2+80, H/2+60);

  // animate thought bubble
  ctx.translate(W/2+80, H/2+60);
  ctx.rotate(Math.sin(t));
  ctx.translate(-W/2-80, -H/2-60);

  ctx.restore();
}
